const view=document.body.dataset.view;
const q=id=>document.getElementById(id);
const escapeText=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(minor,currency='GBP')=>new Intl.NumberFormat('en-GB',{style:'currency',currency}).format((minor||0)/100);
const shortDate=iso=>new Date(iso).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const labelStatus=s=>({approved:'Approved',declined:'Declined',requires_review:'Review required'}[s]||s);
const state={payments:[],merchants:[],selected:'',stats:null};
async function api(path,options){const response=await fetch(path,options);let result;try{result=await response.json()}catch{result={detail:'Invalid response'}}if(!response.ok)throw new Error(typeof result.detail==='string'?result.detail:`Request failed (${response.status})`);return result}
function rowMarkup(t){const merchant=state.merchants.find(m=>m.merchant_id===t.merchant_id)?.display_name||t.merchant_id;return `<tr data-id="${escapeText(t.transaction_id)}" title="Inspect ${escapeText(t.transaction_id)}"><td><span class="tx-id">${escapeText(t.transaction_id)}</span></td><td>${escapeText(merchant)}</td><td>${money(t.amount_minor,t.currency)}</td><td><span class="risk-small">${Number(t.risk_score).toFixed(2)}</span></td><td><span class="status ${escapeText(t.status)}">${labelStatus(t.status)}</span></td><td>${shortDate(t.created_at)}</td><td class="table-cta">↗</td></tr>`}
function renderTable(){const tbody=q('paymentRows');if(!tbody)return;const needle=q('searchPayments')?.value.toLowerCase().trim()||'';const visible=state.payments.filter(t=>[t.transaction_id,t.status,t.request_id].join(' ').toLowerCase().includes(needle));tbody.innerHTML=visible.length?visible.map(rowMarkup).join(''):'<tr><td colspan="7">No matching synthetic transactions.</td></tr>';tbody.querySelectorAll('tr[data-id]').forEach(el=>el.addEventListener('click',()=>showDetails(el.dataset.id)))}
function riskRing(stats){const total=stats.total||1;const a=100*stats.counts.approved/total;const b=100*stats.counts.requires_review/total;return `<div class="risk-ring" style="background:conic-gradient(#95cfa8 0 ${a}%,#f2ce86 ${a}% ${a+b}%,#f0a09a ${a+b}% 100%)"><div class="risk-ring-inner"><strong>${stats.approval_rate}%</strong><small>Approval rate</small></div></div>`}
function drawChart(days){const e=q('volumeChart');if(!e)return;const max=Math.max(1,...days.map(d=>d.volume_minor));e.innerHTML=days.map(d=>`<div class="chart-column"><div class="chart-holder"><div class="chart-bar" title="${escapeText(d.date)}: ${money(d.volume_minor)}" style="height:${Math.max(4,Math.round(d.volume_minor/max*100))}%"></div></div><span class="chart-label">${new Date(d.date+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short'})}</span></div>`).join('')}
function renderStats(stats){if(q('kpiVolume'))q('kpiVolume').textContent=money(stats.approved_volume_minor);if(q('kpiApproval'))q('kpiApproval').textContent=stats.approval_rate+'%';if(q('kpiTransactions'))q('kpiTransactions').textContent=stats.total;if(q('kpiReview'))q('kpiReview').textContent=stats.counts.requires_review;if(q('riskDisplay'))q('riskDisplay').innerHTML=riskRing(stats);if(q('opsTotal'))q('opsTotal').textContent=stats.total;if(q('opsApproved'))q('opsApproved').textContent=stats.counts.approved;if(q('opsReview'))q('opsReview').textContent=stats.counts.requires_review;if(q('opsDeclined'))q('opsDeclined').textContent=stats.counts.declined;drawChart(stats.last_7_days)}
async function loadData(){const mid=view==='merchant'?q('merchantSelect')?.value||'':'';const params=mid?`?merchant_id=${encodeURIComponent(mid)}`:'';const [summary,tx]=await Promise.all([api('/api/dashboard'+params),api('/api/payments'+params)]);state.stats=summary;state.payments=tx.items;renderStats(summary);renderTable();if(q('lastUpdated'))q('lastUpdated').textContent='Updated '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}
async function showDetails(id){const el=q('detailBody');if(!el)return;el.textContent='Loading event evidence…';q('detailModal').showModal();try{const d=await api('/api/payments/'+encodeURIComponent(id));const t=d.transaction;el.innerHTML=`<div class="detail-grid"><div><span class="detail-key">TRANSACTION</span><span class="detail-value">${escapeText(t.transaction_id)}</span></div><div><span class="detail-key">AMOUNT</span><span class="detail-value">${money(t.amount_minor,t.currency)}</span></div><div><span class="detail-key">STATUS</span><span class="status ${escapeText(t.status)}">${labelStatus(t.status)}</span></div><div><span class="detail-key">RISK SCORE</span><span class="detail-value">${Number(t.risk_score).toFixed(3)}</span></div><div><span class="detail-key">REQUEST ID</span><span class="detail-value">${escapeText(t.request_id)}</span></div><div><span class="detail-key">SCORING SIMULATOR</span><span class="detail-value">${escapeText(t.model_version)}</span></div></div><h3>Simulated event trail</h3>${d.events.map(e=>`<div class="event-item"><strong>${escapeText(e.stage)}</strong><small>${shortDate(e.created_at)}</small><code>${escapeText(JSON.stringify(e.details,null,2))}</code></div>`).join('')}`}catch(err){el.textContent=err.message}}
function initPaymentModal(){const m=q('paymentModal');if(!m)return;q('newPayment').addEventListener('click',()=>{q('formKey').value='web-demo-'+crypto.randomUUID();q('formError').textContent='';m.showModal()});q('cancelPayment').addEventListener('click',()=>m.close());q('paymentForm').addEventListener('submit',async e=>{e.preventDefault();const amount=Math.round(Number(q('formAmount').value)*100);const button=q('submitPayment');button.disabled=true;button.textContent='Submitting…';try{const out=await api('/api/payments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({merchant_id:q('formMerchant').value,amount_minor:amount,currency:'GBP',idempotency_key:q('formKey').value,simulate_outcome:q('formOutcome').value})});m.close();if(q('merchantSelect'))q('merchantSelect').value=q('formMerchant').value;await loadData();await showDetails(out.transaction.transaction_id)}catch(err){q('formError').textContent=err.message}finally{button.disabled=false;button.textContent='Create synthetic payment ↗'}})}
async function loadMerchants(){const data=await api('/api/merchants');state.merchants=data.items;for(const id of ['merchantSelect','formMerchant']){const el=q(id);if(!el)continue;el.innerHTML=data.items.map(m=>`<option value="${escapeText(m.merchant_id)}">${escapeText(m.display_name)}</option>`).join('')}if(q('merchantSelect'))q('merchantSelect').value=data.items[0]?.merchant_id||''}
async function loadHypotheses(){if(!q('hypothesisList'))return;const info=await api('/api/ops/insights');q('hypothesisList').innerHTML=info.hypotheses.map(h=>`<div class="hypothesis"><div class="h-top"><strong>${escapeText(h.id)} · ${escapeText(h.area)}</strong><span class="unverified">UNVERIFIED</span></div><p>${escapeText(h.question)}</p></div>`).join('')}
async function start(){try{await loadMerchants();initPaymentModal();await loadData();await loadHypotheses();q('merchantSelect')?.addEventListener('change',loadData);q('refreshPayments')?.addEventListener('click',loadData);q('searchPayments')?.addEventListener('input',renderTable);q('nav-payments')?.addEventListener('click',()=>q('transactions')?.scrollIntoView({behavior:'smooth'}));q('closeDetails')?.addEventListener('click',()=>q('detailModal').close())}catch(err){if(q('paymentRows'))q('paymentRows').innerHTML=`<tr><td colspan="7">Could not load demo data: ${escapeText(err.message)}</td></tr>`;console.error('Kivaryx demo initialization error',err)}}
start();
